function im = makediag(m,n)% makediag -- Make a diagonal pattern%  Usage%    im = makediag(m,n)% Inputs%    m,n  size of desired image% Outputs%    im   m by n imageim = zeros(m,n);for i=1:m,  t = (i-.5)*n/m;  im(i,1:floor(t)) = ones(1,floor(t));  if floor(t) < t,    im(i,ceil(t)) = t - floor(t);  endend        %   % Part of WaveLab Version 802% Built Sunday, October 3, 1999 8:52:27 AM% This is Copyrighted Material% For Copying permissions see COPYING.m% Comments? e-mail wavelab@stat.stanford.edu%       